mapper.update:
UPDATE spectra_core.scheduler_loop_runtime
SET status = 'RUNNING',
    last_heartbeat_at = #{heartbeatAt},
    lease_expires_at = #{leaseExpiresAt},
    updated_at = CURRENT_TIMESTAMP,
    version = version + 1
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND instance_id = #{instanceId}
  AND status = 'STARTING'

UPDATE spectra_core.scheduler_loop_runtime
SET last_heartbeat_at = #{heartbeatAt},
    lease_expires_at = #{leaseExpiresAt},
    updated_at = CURRENT_TIMESTAMP,
    version = version + 1
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND instance_id = #{instanceId}
  AND status IN ('RUNNING', 'DEGRADED', 'DRAINING')
  AND (lease_expires_at IS NULL OR lease_expires_at >= #{heartbeatAt})
